def provider_stop_receipt(config: dict[str, object]) -> dict[str, object] | None:
    """Read the retained refusal; never clear or rewrite the original STOP."""
    selected = config.get("live_stop_receipt")
    if not selected:
        return None
    path = Path(str(selected))
    raw = path.read_bytes()
    original = json.loads(raw)
    if not isinstance(original, dict) or not original.get("failure_reason"):
        raise RuntimeError("The configured provider STOP receipt is invalid")
    return {
        "path": str(path),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "original": original,
    }

